  "name": "task-progress",
  "version": "0.1.0",
  "description": "A progress row above the prompt for each plan the model reports, plus a row per running subagent. The bar shows what the model reports; it costs no tokens to draw.",
  "author": {
    "name": "Stylus Nexus"
