  "userConfig": {
    "doneBarSeconds": {
      "type": "number",
      "title": "Keep finished plans (seconds)",
      "description": "How long a finished plan's row stays above the prompt before it leaves.",
      "default": 30,
      "min": 0,
      "max": 3600
    }
  },
